<template><div class="app-container"><h1>出餐排队</h1><p>按制作状态、预约备餐时间和接单等待时间排序，每15秒更新。预计时间按并行制作单数及每单制作时长估算。</p><el-select style="width:260px;margin-right:12px" v-model="storeId" filterable remote :remote-method="findStores" placeholder="选择店铺" @change="load"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-button :loading="loading" @click="load">刷新排队</el-button><el-table :data="rows" :row-class-name="({row})=>row.queue.overdue?'overdue':''" style="margin-top:24px"><el-table-column type="index" label="顺序" width="70"/><el-table-column prop="id" label="订单编号" min-width="200"/><el-table-column label="待制作餐品 / 备注" min-width="220"><template #default="{row}"><div v-for="p in row.items" :key="p.id">{{p.name}} ×{{p.quantity-p.refunded_quantity}}<div style="font-size:12px;color:#71816c">{{p.option_text}}</div></div><div v-if="row.remark">备注：{{row.remark}}</div></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column label="预约 / 开始备餐" min-width="180"><template #default="{row}">{{row.scheduled_at||'尽快制作'}}<div>{{row.prepare_at||''}}</div></template></el-table-column><el-table-column label="预计出餐" min-width="190"><template #default="{row}">{{String(row.queue.estimatedReadyAt).replace('T',' ').slice(0,16)}}<div>约 {{row.queue.minutes}} 分钟 · 前方 {{row.queue.ahead}} 单</div></template></el-table-column><el-table-column label="等待提醒" min-width="150"><template #default="{row}"><el-tag v-if="row.queue.overdue" type="danger">已超原预计 {{row.queue.overdueMinutes}} 分钟</el-tag><el-tag v-else-if="row.queue.waitingForSchedule" type="info">尚未到备餐时间</el-tag><span v-else>正常排队</span></template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button v-if="row.status==='PENDING'&&allowed(scope,row.store_id,'ORDER')" :disabled="busy||row.queue.waitingForSchedule" @click="advance(row,'PREPARING')">接单制作</el-button><el-button v-if="row.status==='PREPARING'&&allowed(scope,row.store_id,'COOK')" :disabled="busy" type="primary" @click="advance(row,row.type==='PICKUP'?'READY':'WAITING_DELIVERY')">餐品已备好</el-button></template></el-table-column></el-table><p v-if="!rows.length">当前没有等待制作的订单。退款审核中的订单暂停排队。</p></div></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import {foodGet,foodPost,statuses} from '@/api/food';import {allowed} from '../permissions';import {ElMessageBox} from 'element-plus';const stores=ref([]),storeId=ref(),rows=ref([]),scope=ref({}),loading=ref(false),busy=ref(false);let timer,revision=0;async function findStores(q=''){stores.value=(await foodGet('/catalog/stores',{q,pageSize:100})).data.rows}async function load(){if(!storeId.value)return;const ticket=++revision;loading.value=true;try{const r=await foodGet('/kitchen',{storeId:storeId.value});if(ticket===revision)rows.value=r.data}finally{if(ticket===revision)loading.value=false}}async function advance(row,status){try{await ElMessageBox.confirm(status==='PREPARING'?'确认开始制作？':'确认餐品已备好？','更新出餐进度')}catch{return}busy.value=true;try{await foodPost('/orders/'+row.id+'/status',{status});await load()}finally{busy.value=false}}onMounted(async()=>{scope.value=(await foodGet('/scope')).data;await findStores();storeId.value=stores.value[0]?.id;await load();timer=setInterval(()=>{if(!loading.value&&!busy.value)load()},15000)});onBeforeUnmount(()=>{revision++;clearInterval(timer)})
</script><style scoped>p{color:#7b8875;line-height:1.8}:deep(.overdue){--el-table-tr-bg-color:#fff0eb}</style>
